import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.D7WGirly.js";const c=JSON.parse('{"title":"Copilot — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"copilot-02-how-tos-and-workflows.md","filePath":"copilot-02-how-tos-and-workflows.md"}'),n={name:"copilot-02-how-tos-and-workflows.md"};function r(s,e,l,u,p,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="copilot-—-how-tos-workflows" tabindex="-1">Copilot — How-tos &amp; Workflows <a class="header-anchor" href="#copilot-—-how-tos-workflows" aria-label="Permalink to &quot;Copilot — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for using Copilot effectively</em></p><hr><h2 id="opening-copilot" tabindex="-1">Opening Copilot <a class="header-anchor" href="#opening-copilot" aria-label="Permalink to &quot;Opening Copilot&quot;">​</a></h2><ol><li>Click <strong>Copilot</strong> in the left-hand navigation bar.</li><li>The Copilot chat panel opens over your current page.</li><li>Type your message and press Enter (or click the send button).</li></ol><p>To close Copilot, click <strong>Copilot</strong> again in the sidebar, or use the close control inside the panel. Your current page is unaffected.</p><hr><h2 id="asking-questions-about-lodestone" tabindex="-1">Asking Questions About Lodestone <a class="header-anchor" href="#asking-questions-about-lodestone" aria-label="Permalink to &quot;Asking Questions About Lodestone&quot;">​</a></h2><p>Use plain language. You don&#39;t need to use special commands.</p><p><strong>Examples:</strong></p><ul><li>&quot;What is a Bento Grid?&quot;</li><li>&quot;How do I set up the Gong integration?&quot;</li><li>&quot;What&#39;s the difference between Actual and Forecast mode in a Release?&quot;</li><li>&quot;When should I use Top-Down vs Bottom-Up Strategy?&quot;</li></ul><p>Copilot draws from the Lodestone knowledge base to answer accurately. If you get an incomplete answer, try rephrasing or asking a follow-up — Copilot maintains the context of your conversation within the session.</p><hr><h2 id="asking-questions-about-product-management" tabindex="-1">Asking Questions About Product Management <a class="header-anchor" href="#asking-questions-about-product-management" aria-label="Permalink to &quot;Asking Questions About Product Management&quot;">​</a></h2><p>Copilot also knows product management frameworks and best practices. Ask it anything you&#39;d ask a senior PM or a PM handbook.</p><p><strong>Examples:</strong></p><ul><li>&quot;Explain the RICE prioritization framework&quot;</li><li>&quot;What should a good PRD include?&quot;</li><li>&quot;How do I run a Buy-a-Feature workshop?&quot;</li><li>&quot;What&#39;s the difference between an OKR and a strategic initiative?&quot;</li></ul><hr><h2 id="taking-actions-in-your-workspace" tabindex="-1">Taking Actions in Your Workspace <a class="header-anchor" href="#taking-actions-in-your-workspace" aria-label="Permalink to &quot;Taking Actions in Your Workspace&quot;">​</a></h2><p>When you want Copilot to do something for you, phrase it as an instruction.</p><h3 id="creating-a-feature" tabindex="-1">Creating a Feature <a class="header-anchor" href="#creating-a-feature" aria-label="Permalink to &quot;Creating a Feature&quot;">​</a></h3><blockquote><p>&quot;Create a feature called API Rate Limiting&quot;</p></blockquote><p>Copilot will create the feature in your backlog and confirm with a link.</p><h3 id="finding-features" tabindex="-1">Finding Features <a class="header-anchor" href="#finding-features" aria-label="Permalink to &quot;Finding Features&quot;">​</a></h3><blockquote><p>&quot;Show me all In Progress features&quot;<br> &quot;List features with &#39;auth&#39; in the name&quot;</p></blockquote><h3 id="updating-a-feature" tabindex="-1">Updating a Feature <a class="header-anchor" href="#updating-a-feature" aria-label="Permalink to &quot;Updating a Feature&quot;">​</a></h3><blockquote><p>&quot;Set the SSO feature to Completed&quot;<br> &quot;Update the description of FEAT-7 to say it handles OAuth 2.0 flows&quot;</p></blockquote><h3 id="adding-a-feature-to-a-roadmap" tabindex="-1">Adding a Feature to a Roadmap <a class="header-anchor" href="#adding-a-feature-to-a-roadmap" aria-label="Permalink to &quot;Adding a Feature to a Roadmap&quot;">​</a></h3><blockquote><p>&quot;Add the SSO feature to the Q3 roadmap&quot;</p></blockquote><p>If Copilot needs to find the right feature or roadmap, it will search your workspace automatically. If there&#39;s ambiguity (e.g. two features with similar names), it may ask you to clarify.</p><h3 id="generating-documents-for-a-feature" tabindex="-1">Generating Documents for a Feature <a class="header-anchor" href="#generating-documents-for-a-feature" aria-label="Permalink to &quot;Generating Documents for a Feature&quot;">​</a></h3><blockquote><p>&quot;Generate a PRD for the SSO feature&quot;<br> &quot;Create user stories for FEAT-12&quot;<br> &quot;Write an Opportunity Canvas for the mobile app feature&quot;</p></blockquote><p>Copilot locates the feature in your backlog and triggers document generation. The document is created and available in the feature&#39;s detail page.</p><h3 id="creating-roadmaps-releases-and-strategies" tabindex="-1">Creating Roadmaps, Releases, and Strategies <a class="header-anchor" href="#creating-roadmaps-releases-and-strategies" aria-label="Permalink to &quot;Creating Roadmaps, Releases, and Strategies&quot;">​</a></h3><blockquote><p>&quot;Create a roadmap called 2027 Vision&quot;<br> &quot;Create a release called v3.0&quot;<br> &quot;Create a strategy named Platform Expansion&quot;</p></blockquote><p>Copilot creates the object and returns a confirmation with a direct link.</p><hr><h2 id="chaining-actions-in-one-conversation" tabindex="-1">Chaining Actions in One Conversation <a class="header-anchor" href="#chaining-actions-in-one-conversation" aria-label="Permalink to &quot;Chaining Actions in One Conversation&quot;">​</a></h2><p>Because Copilot remembers the context of your conversation, you can chain actions without repeating yourself.</p><p><strong>Example sequence:</strong></p><ol><li>&quot;Create a feature called Dark Mode&quot;</li><li>&quot;Add it to the Q4 roadmap&quot;</li><li>&quot;Generate an Opportunity Canvas for it&quot;</li><li>&quot;Now set its status to In Progress&quot;</li></ol><p>Each follow-up builds on what was already done — you don&#39;t need to name the feature again.</p><hr><h2 id="what-happens-when-copilot-isn-t-sure" tabindex="-1">What Happens When Copilot Isn&#39;t Sure <a class="header-anchor" href="#what-happens-when-copilot-isn-t-sure" aria-label="Permalink to &quot;What Happens When Copilot Isn&#39;t Sure&quot;">​</a></h2><p>If Copilot can&#39;t find the object you&#39;re referring to, it will ask for clarification rather than guessing. If it can&#39;t complete an action due to a permission issue or missing data, it will tell you what&#39;s needed.</p><p>If the response doesn&#39;t seem right, try being more specific — including a feature key (like FEAT-7) or a full name is more reliable than a partial name when multiple similar items exist.</p><hr><p><em>Next: Advanced Features &amp; Customization — getting the most from Copilot, rate limits, and using Copilot alongside other modules.</em></p>',48)])])}const g=t(n,[["render",r]]);export{c as __pageData,g as default};
